package com.flippingfriend.companion;
import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementExpectedSlotOccupancyEvaluatorTest {
 @Test public void appliesProductionThreeOutcomeFormulaInOrder(){BuyReplacementCalibratedDurationEvaluationSet s=source();BuyReplacementExpectedSlotOccupancyEvaluationSet r=new BuyReplacementExpectedSlotOccupancyEvaluator().evaluate(s,1100);assertNotNull(r);assertEquals(s.getEvaluations().size(),r.getEvaluations().size());for(int i=0;i<r.getEvaluations().size();i++){BuyReplacementCalibratedDurationEvaluation a=s.getEvaluations().get(i);BuyReplacementExpectedSlotOccupancyEvaluation e=r.getEvaluations().get(i);double completed=a.getBuyProbability()*a.getSellProbability();double stranded=a.getBuyProbability()*(1-a.getSellProbability());double neverBought=1-a.getBuyProbability();double expected=Math.max(1.0/60.0,neverBought*s.getEffectiveHorizonHours()+completed*(a.getCalibratedBuyHours()+a.getCalibratedSellHours())+stranded*(a.getCalibratedBuyHours()+s.getEffectiveHorizonHours()));assertEquals(expected,e.getExpectedSlotHours(),0.0);assertEquals(a.getSellOffsetIndex(),e.getSellOffsetIndex());}try{r.getEvaluations().clear();fail("immutable");}catch(UnsupportedOperationException expected){}}
 @Test public void unavailableAndStaleInputsFailClosed(){BuyReplacementExpectedSlotOccupancyEvaluator e=new BuyReplacementExpectedSlotOccupancyEvaluator();assertNull(e.evaluate(null,1100));assertNull(e.evaluate(source(),1221));}
 @Test public void contractsCarryNoProfitRiskRankingSelectionOrAuthorization()throws Exception{for(String f:new String[]{"BuyReplacementExpectedSlotOccupancyEvaluation.java","BuyReplacementExpectedSlotOccupancyEvaluationSet.java"}){String s=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/java/com/flippingfriend/companion/"+f));for(String x:new String[]{"expectedProfit","unwindLoss","worstLoss","kelly","expectedGpPerSlotHour","selected","score","rank","PortfolioCandidate","PolicyDecision","OfferLifecycleAction","REPLACEMENT_AUTHORIZED"})assertFalse(s.contains(x));}}
 private static BuyReplacementCalibratedDurationEvaluationSet source(){return BuyReplacementCalibratedDurationEvaluatorTest.evaluationSetForCompanionTests();}
}
